CREATE TYPE public.app_role AS ENUM ('admin','collector');
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'collector', collector_id uuid REFERENCES public.collectors(id), CONSTRAINT collector_identity CHECK (role = 'collector' OR collector_id IS NULL));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') $$;
CREATE FUNCTION public.can_access_customer(cid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_admin() OR EXISTS(SELECT 1 FROM public.customers c JOIN public.zones z ON z.id=c.zone_id JOIN public.user_roles r ON r.collector_id=z.collector_id WHERE c.id=cid AND r.user_id=auth.uid() AND r.role='collector') $$;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE POLICY roles_manage ON public.user_roles FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
GRANT INSERT,UPDATE,DELETE ON public.user_roles TO authenticated;
REVOKE ALL ON FUNCTION public.is_admin(), public.can_access_customer(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_admin(), public.can_access_customer(uuid) TO authenticated,service_role;
ALTER TABLE public.customers ADD COLUMN billing_start_month date NOT NULL DEFAULT date_trunc('month',CURRENT_DATE)::date, ADD COLUMN billing_day integer NOT NULL DEFAULT 10 CHECK(billing_day BETWEEN 1 AND 28), ADD COLUMN recurring_enabled boolean NOT NULL DEFAULT true;
UPDATE public.customers SET billing_start_month=CASE WHEN due_amount=0 THEN date_trunc('month',due_date-interval '1 month')::date ELSE date_trunc('month',due_date)::date END, billing_day=least(28,extract(day from due_date)::int);
CREATE TABLE public.monthly_bills (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES public.customers(id),billing_month date NOT NULL CHECK(extract(day from billing_month)=1),amount numeric(12,2) NOT NULL CHECK(amount>=0),due_date date NOT NULL,opening_paid numeric(12,2) NOT NULL DEFAULT 0 CHECK(opening_paid>=0 AND opening_paid<=amount),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(customer_id,billing_month));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.monthly_bills TO authenticated; GRANT ALL ON public.monthly_bills TO service_role;
ALTER TABLE public.monthly_bills ENABLE ROW LEVEL SECURITY;
CREATE POLICY bills_read ON public.monthly_bills FOR SELECT TO authenticated USING(public.can_access_customer(customer_id));
CREATE POLICY bills_manage ON public.monthly_bills FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE INDEX monthly_bills_month_due ON public.monthly_bills(billing_month,due_date); CREATE INDEX customers_zone ON public.customers(zone_id);
INSERT INTO public.monthly_bills(customer_id,billing_month,amount,due_date,opening_paid) SELECT c.id,(date_trunc('month',c.due_date)-(s.n * interval '1 month'))::date, CASE WHEN c.due_amount=0 THEN c.monthly_bill ELSE least(c.monthly_bill,c.due_amount-s.n*c.monthly_bill) END,(c.due_date-s.n*interval '1 month')::date,CASE WHEN c.due_amount=0 THEN c.monthly_bill ELSE 0 END FROM public.customers c CROSS JOIN LATERAL generate_series(0,CASE WHEN c.due_amount=0 OR c.monthly_bill<=0 THEN 0 ELSE greatest(0,ceil(c.due_amount/c.monthly_bill)::int-1) END) s(n) WHERE c.monthly_bill>0;
INSERT INTO public.monthly_bills(customer_id,billing_month,amount,due_date) SELECT id,date_trunc('month',due_date)::date,due_amount,due_date FROM public.customers WHERE monthly_bill<=0 AND due_amount>0 ON CONFLICT DO NOTHING;
ALTER TABLE public.payments ADD COLUMN collection_key uuid UNIQUE, ADD COLUMN allocated boolean NOT NULL DEFAULT false, ADD COLUMN voided_at timestamptz, ADD COLUMN void_reason text;
CREATE TABLE public.payment_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_id uuid NOT NULL REFERENCES public.payments(id),bill_id uuid NOT NULL REFERENCES public.monthly_bills(id),amount numeric(12,2) NOT NULL CHECK(amount>0),UNIQUE(payment_id,bill_id));
GRANT SELECT ON public.payment_allocations TO authenticated; GRANT ALL ON public.payment_allocations TO service_role;
ALTER TABLE public.payment_allocations ENABLE ROW LEVEL SECURITY;
CREATE POLICY allocations_read ON public.payment_allocations FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.monthly_bills b WHERE b.id=bill_id AND public.can_access_customer(b.customer_id)));
CREATE INDEX allocations_bill ON public.payment_allocations(bill_id);
CREATE VIEW public.bill_balances WITH (security_invoker=true) AS SELECT b.*,greatest(0,b.amount-b.opening_paid-coalesce((SELECT sum(a.amount) FROM public.payment_allocations a JOIN public.payments p ON p.id=a.payment_id WHERE a.bill_id=b.id AND p.voided_at IS NULL),0)) AS outstanding FROM public.monthly_bills b;
GRANT SELECT ON public.bill_balances TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.apply_payment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.customers SET last_payment_date=NEW.paid_on,last_payment_amount=NEW.amount WHERE id=NEW.customer_id; RETURN NEW; END $$;
COMMENT ON COLUMN public.customers.due_amount IS 'DEPRECATED: total is derived from monthly bills and payment allocations';
COMMENT ON COLUMN public.customers.due_date IS 'DEPRECATED: each monthly bill has its own due_date';
CREATE FUNCTION public.generate_monthly_bills() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.monthly_bills(customer_id,billing_month,amount,due_date) SELECT c.id,m::date,c.monthly_bill,(m+(c.billing_day-1)*interval '1 day')::date FROM public.customers c CROSS JOIN LATERAL generate_series(c.billing_start_month,date_trunc('month',timezone('Asia/Dhaka',now())),interval '1 month') m WHERE c.recurring_enabled AND c.monthly_bill>0 ON CONFLICT(customer_id,billing_month) DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.generate_monthly_bills() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.generate_monthly_bills() TO service_role;
CREATE FUNCTION public.sync_billing() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Staff assignment required'; END IF; RETURN public.generate_monthly_bills(); END $$;
REVOKE ALL ON FUNCTION public.sync_billing() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.sync_billing() TO authenticated;
CREATE FUNCTION public.collect_months(p_customer uuid,p_allocations jsonb,p_method text,p_date date,p_receipt text,p_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid; total numeric:=0; entry jsonb; bid uuid; amt numeric; bal numeric; col uuid; BEGIN IF NOT public.can_access_customer(p_customer) THEN RAISE EXCEPTION 'Not assigned to this customer'; END IF; IF p_method NOT IN ('cash','bkash','nagad','rocket','bank') OR p_date IS NULL OR p_date>timezone('Asia/Dhaka',now())::date OR p_key IS NULL THEN RAISE EXCEPTION 'Invalid payment details'; END IF; PERFORM 1 FROM public.customers WHERE id=p_customer FOR UPDATE; SELECT id INTO pid FROM public.payments WHERE collection_key=p_key; IF pid IS NOT NULL THEN RETURN pid; END IF; IF jsonb_typeof(p_allocations)<>'array' OR jsonb_array_length(p_allocations)=0 OR jsonb_array_length(p_allocations)>120 THEN RAISE EXCEPTION 'Select billing months'; END IF; IF (SELECT count(*) FROM jsonb_array_elements(p_allocations))<>(SELECT count(DISTINCT e->>'bill_id') FROM jsonb_array_elements(p_allocations)e) THEN RAISE EXCEPTION 'Duplicate billing month'; END IF; FOR entry IN SELECT * FROM jsonb_array_elements(p_allocations) LOOP bid:=(entry->>'bill_id')::uuid; amt:=(entry->>'amount')::numeric; SELECT outstanding INTO bal FROM public.bill_balances WHERE id=bid AND customer_id=p_customer; IF bal IS NULL OR amt IS NULL OR amt<=0 OR amt>bal OR amt<>round(amt,2) OR amt='NaN'::numeric THEN RAISE EXCEPTION 'Payment exceeds outstanding or amount is invalid'; END IF; total:=total+amt; END LOOP; SELECT z.collector_id INTO col FROM public.customers c LEFT JOIN public.zones z ON z.id=c.zone_id WHERE c.id=p_customer; INSERT INTO public.payments(customer_id,collector_id,amount,method,paid_on,receipt_no,created_by,collection_key,allocated) VALUES(p_customer,col,total,p_method,p_date,nullif(trim(p_receipt),''),auth.uid(),p_key,true) RETURNING id INTO pid; INSERT INTO public.payment_allocations(payment_id,bill_id,amount) SELECT pid,(e->>'bill_id')::uuid,(e->>'amount')::numeric FROM jsonb_array_elements(p_allocations)e; RETURN pid; END $$;
REVOKE ALL ON FUNCTION public.collect_months(uuid,jsonb,text,date,text,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.collect_months(uuid,jsonb,text,date,text,uuid) TO authenticated;
CREATE FUNCTION public.void_collection(p_payment uuid,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() OR length(trim(p_reason))<3 THEN RAISE EXCEPTION 'Admin and reason required'; END IF; UPDATE public.payments SET voided_at=now(),void_reason=trim(p_reason) WHERE id=p_payment AND allocated AND voided_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Only new allocated collections can be reversed'; END IF; END $$;
REVOKE ALL ON FUNCTION public.void_collection(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.void_collection(uuid,text) TO authenticated;
DROP POLICY "staff all customers" ON public.customers; DROP POLICY "staff all zones" ON public.zones; DROP POLICY "staff all collectors" ON public.collectors; DROP POLICY "staff read payments" ON public.payments; DROP POLICY "staff add payments" ON public.payments;
CREATE POLICY customers_read ON public.customers FOR SELECT TO authenticated USING(public.can_access_customer(id)); CREATE POLICY customers_manage ON public.customers FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY zones_read ON public.zones FOR SELECT TO authenticated USING(public.is_admin() OR EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.collector_id=zones.collector_id)); CREATE POLICY zones_manage ON public.zones FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY collectors_read ON public.collectors FOR SELECT TO authenticated USING(public.is_admin() OR EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.collector_id=collectors.id)); CREATE POLICY collectors_manage ON public.collectors FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
CREATE POLICY payments_read ON public.payments FOR SELECT TO authenticated USING(public.can_access_customer(customer_id)); REVOKE INSERT,UPDATE,DELETE ON public.payments FROM authenticated;
CREATE FUNCTION public.validate_monthly_bill() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE paid numeric; BEGIN IF TG_OP='DELETE' THEN IF EXISTS(SELECT 1 FROM public.payment_allocations WHERE bill_id=OLD.id) OR OLD.opening_paid>0 THEN RAISE EXCEPTION 'Paid bills cannot be deleted'; END IF; RETURN OLD; END IF; IF TG_OP='INSERT' AND NEW.opening_paid<>0 AND auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'Record a collection instead'; END IF; IF TG_OP='UPDATE' THEN IF NEW.customer_id<>OLD.customer_id OR NEW.billing_month<>OLD.billing_month OR NEW.opening_paid<>OLD.opening_paid THEN RAISE EXCEPTION 'Bill identity and historical credit cannot change'; END IF; SELECT coalesce(sum(a.amount),0)+OLD.opening_paid INTO paid FROM public.payment_allocations a JOIN public.payments p ON p.id=a.payment_id WHERE a.bill_id=OLD.id AND p.voided_at IS NULL; IF NEW.amount<paid THEN RAISE EXCEPTION 'Amount cannot be below payments'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_monthly_bill BEFORE INSERT OR UPDATE OR DELETE ON public.monthly_bills FOR EACH ROW EXECUTE FUNCTION public.validate_monthly_bill();
CREATE EXTENSION IF NOT EXISTS pg_cron;
SELECT cron.schedule('billmap-monthly-billing','5 18 1 * *','SELECT public.generate_monthly_bills()');